import{_ as n,l,o as e,c as p,v as t,p as i,x as r,d as s,i as u,S as d}from"./chunks/framework.InCnrqk-.js";const f=JSON.parse('{"title":"关键期限 DV01","description":"","frontmatter":{"title":"关键期限 DV01","date":"2026-09-07T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/key-tenor-dv01.md","filePath":"quant/key-tenor-dv01.md","lastUpdated":1789023840000}'),h={name:"quant/key-tenor-dv01.md"};function D(m,a,E,c,V,A){const o=l("Mermaid");return e(),p("div",null,[a[1]||(a[1]=t('<h1 id="关键期限-dv01" tabindex="-1">关键期限 DV01 <a class="header-anchor" href="#关键期限-dv01" aria-label="Permalink to &quot;关键期限 DV01&quot;">​</a></h1><div class="epigraph"><p>关键利率久期把形状风险收成一组相对敏感；交易与 PnL 需要的是每个关键期限上「一基点值多少钱」的向量，以便直接解对冲名义。</p><footer>—— 对照 Ho, Key Rate Durations, Journal of Fixed Income, 1992；Golub &amp; Tilman, Journal of Portfolio Management, 1997</footer></div><p>修正久期和 DV01 描述平行移动；<a href="/quant/key-rate-duration">关键利率久期</a>（KRD）把平行拆成三角形局部平移，单位仍是「相对价格 / 收益率」。关键期限 DV01（key-tenor DV01, bucketed PV01）是同一组冲击的货币化：第 \\(j\\) 个关键点上移 1bp，组合价值变动多少元。Ho（1992）给出冲击的几何；Golub 与 Tilman（1997）把关键利率与 PCA、VaR 放进同一张风险表。本篇写 DV01 向量如何从曲线雅可比算出、它与 KRD 差一个价格因子、以及多曲线下矩阵为什么必须按「哪一条曲线、哪一个期限」展开。它补足 <a href="/quant/duration-convexity">久期、凸性</a> 的标量 01，并给<a href="/quant/curve-butterfly">曲线蝶式</a>、<a href="/quant/swap-spread">互换价差</a>、<a href="/quant/basis-swap">基差互换</a> 提供对冲的线性代数。短端模型的希腊字母要先映射到这些可交易桶，见 <a href="/quant/hull-white">Hull-White</a> 与 <a href="/quant/hjm">HJM</a>。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>风控限额和交易员的下单单位是名义与美元（或人民币）01，不是久期年数。同一 KRD，面值一亿与面值一千万的货币风险差十倍。把 KRD 乘以现价再乘 1bp，在线性产品上得到关键期限 DV01；含权产品必须直接对全价做差分，因为有效久期随状态变。问题是冲击定义：扰动市场报价再重新自助，还是扰动已插值的曲线节点？前者与可交易工具对齐，后者与 Ho 的三角形对齐；二者在全局插值下会对不齐，10Y 互换 bump 会污染 30Y 远期。</p><p>第二个问题是共线性。关键点取 1Y、2Y、3Y、5Y、7Y、10Y、15Y、20Y、30Y 时，相邻互换高度相关，把组合 DV01 向量投到工具篮子上会得到巨大的反向名义。Golub–Tilman 同时报告 PCA：用三因子解释大部分方差，关键 01 负责局部残差。只用满桶 DV01 对冲，是在交易噪声。</p><h3 id="krd-与-dv01-的换算" tabindex="-1">KRD 与 DV01 的换算 <a class="header-anchor" href="#krd-与-dv01-的换算" aria-label="Permalink to &quot;KRD 与 DV01 的换算&quot;">​</a></h3><p>对第 \\(j\\) 个关键冲击 \\(\\Delta=10^{-4}\\)，</p> \\[\\mathrm{DV01}_j = P^{(j)}-P, \\qquad \\mathrm{KRD}_j = -\\frac{1}{P}\\frac{P^{(j)}-P}{\\Delta}. \\]<p>因而 \\(\\mathrm{DV01}_j \\approx -P\\cdot\\mathrm{KRD}_j\\cdot\\Delta\\)。符号惯例必须钉死：许多系统把 DV01 做成「收益率上升时的亏损为正」，与数学差分差一个负号。跨系统加总前先对符号做对表。平行 DV01 应约等于 \\(\\sum_j\\mathrm{DV01}_j\\)（线性插值、同向 1bp 时）；加总失败说明泄漏或边界外推，是实现测试，见 Ho 篇。</p><p><span class="marginnote">DV01、PV01、CS01、IR01 不是同义词。CS01 是信用利差 01；IR01 有时只指折现曲线。文档应写「SOFR 10Y par DV01」而不是「利率 01」。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p><strong>工具 bump。</strong> 对每个关键互换（或国债、OIS）把市场平价上移 1bp，其余报价不变，按原规则重新<a href="/quant/curve-bootstrap">自助</a>，重估组合。得到的是对可交易报价的雅可比，最适合解对冲：若 \\(J\\) 是工具 DV01 矩阵（列=对冲工具，行=组合在各桶的敏感，或直接一维组合对工具报价的梯度），名义 \\(x\\) 满足 \\(J x = -\\mathrm{DV01}_{\\mathrm{port}}\\)。这是关键期限 DV01 的本职工作。</p><p><strong>节点 bump。</strong> 在零息或远期节点上做 Ho 三角形，保持报价不变、只动插值。适合解释「曲线形状」和与 KRD 对照，但篮子对冲还要再乘一层报价对节点的雅可比。两种 bump 都应存在，并定期对账：差异来自插值泄漏、曲线构建约束（正远期、平滑）和固定端日计数。</p><p><strong>多曲线矩阵。</strong> 行是组合，列是 \\(({\\text{曲线}},{\\text{期限}})\\)：SOFR 折现 2Y/5Y/10Y/30Y，投影 3M 的同样期限，国债曲线，可能还有<a href="/quant/swap-spread">互换价差</a> 与期限<a href="/quant/basis-swap">基差</a>。对冲工具必须落在同一格子上，否则 10Y 互换会同时动折现与投影，看起来像对冲了国债 10Y。跨币种再加<a href="/quant/xccy-basis">交叉货币基差</a> 列。</p><h3 id="从模型希腊字母到桶" tabindex="-1">从模型希腊字母到桶 <a class="header-anchor" href="#从模型希腊字母到桶" aria-label="Permalink to &quot;从模型希腊字母到桶&quot;">​</a></h3><p>Hull–White 对短端 \\(r\\) 的 delta 不是可交易 01。标准做法是扰动市场曲线、重解 \\(\\theta(t)\\)、重定价，得到关键期限 DV01——承认一因子几乎把所有桶变成共线。HJM 与 LMM 可以对每个远期给出解析或半解析的 01，再聚合成关键点；相关结构决定聚合后的条件数。<a href="/quant/bermudan-swaption">百慕大</a> 与 <a href="/quant/cms-convexity">CMS</a> 的有效 01 状态依赖，应用当日全价差分，并在大场景下重定价，而不是把昨日线性向量乘 \\(\\Delta y\\)。</p><p>PnL 解释：</p> \\[\\Delta P \\approx \\sum_{c,j}\\mathrm{DV01}_{c,j}\\,\\Delta y_{c,j} + \\text{凸性} + \\text{theta} + \\text{残差}. \\]<p>残差应监控：持续的残差表示关键点太稀、插值与市场冲击不一致，或含权凸性被线性项丢掉。不要把残差当 alpha。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>关键期限 DV01 把无穷维曲线梯度投到有限个可交易方向上。三角形基使「动 10Y」在相邻关键点为 0，中间线性，从而与 10Y 工具的风险大体对齐。对冲比是货币 01 之比：组合 10Y DV01 为 \\(-8\\) 万元/bp，对冲工具为 \\(-2\\) 万元/bp 每单位名义，则需要约 4 单位名义。泄漏来自工具自身也有相邻桶 01，必须解向量而不是逐桶独立打零——与 KRD 篇同一句话，只是现在单位是钱。</p><p>PCA 三因子是这组向量的低秩近似：水平约各桶之和，斜率约长减短，曲率约<a href="/quant/curve-butterfly">蝶式</a>。Golub–Tilman 建议两层：用 PCA 管可交易的大方差，用关键 01 管折缝。只有关键 01 时，交易员会对每一个 1bp 噪声下单；只有 PCA 时，7Y 的局部折缝会对冲到 5Y 与 10Y 上留下残差。</p><p><span class="marginnote">1bp 差分与 10bp 有效 01 因凸性而不同。限额、对冲、PnL 解释必须用同一冲击大小。含权账簿用 1bp 线性 01 去对冲 50bp 情景，是已知的缺口，应另设备兑情景。</span></p><h3 id="远期-dv01-与平价-dv01" tabindex="-1">远期 DV01 与平价 DV01 <a class="header-anchor" href="#远期-dv01-与平价-dv01" aria-label="Permalink to &quot;远期 DV01 与平价 DV01&quot;">​</a></h3><p>平价 DV01 扰动平价收益率或平价互换报价；远期 DV01 扰动瞬时或简单远期节点。后者更接近 HJM/LMM 的状态，前者更接近经纪商报价。把 LMM 的 caplet 01 直接当成 10Y 平价 01，中间隔着年金权重。系统应标明坐标。信用曲线的 CS01 是利差关键期限上的同类对象，与利率 DV01 分列，见<a href="/quant/reduced-form-intensity">简化形式强度</a>；不要加总成一个「10Y 敏感」。</p><h2 id="边界与工程取舍" tabindex="-1">边界与工程取舍 <a class="header-anchor" href="#边界与工程取舍" aria-label="Permalink to &quot;边界与工程取舍&quot;">​</a></h2><p>关键点集合要稳定，像会计科目；哪一个桶 01 大可以变。点过多则 \\(J^\\top J\\) 病态，应对名义加 Tikhonov 或先投到 PCA。插值必须局部，否则 Ho 三角形在引擎里不是三角形。外汇、通胀、信用各自一张矩阵。A 股与政策短端高度绑定，短端桶的 01 可能被一个逆回购操作同时推动，条件数和流动性都与美债不同。</p><p>不要用模型内对冲（只对冲 \\(r\\) 或只对冲前三个 LMM 因子）替代关键期限 DV01 限额：模型内中性在市场里仍有斜率与折缝。反过来，也不要把关键 01 当成定价模型。它是风险的坐标。</p><p><span class="marginnote">实现测试：单位名义的 10Y 平价互换，其 10Y 关键 DV01 应接近该互换自身的 PV01，相邻桶应接近零（在局部插值下）。若 30Y 桶出现明显 01，自助泄漏，先修曲线再修对冲。</span></p>',30)),(e(),i(d,null,{default:r(()=>[u(o,{id:"mermaid-84",class:"mermaid",graph:"flowchart%20TD%0A%20%20Q%5B%22%E5%B8%82%E5%9C%BA%E6%8A%A5%E4%BB%B7%22%5D%20--%3E%20B1%5B%22%E5%B7%A5%E5%85%B7%20bump%20%E5%86%8D%E8%87%AA%E5%8A%A9%22%5D%0A%20%20NODE%5B%22%E6%9B%B2%E7%BA%BF%E8%8A%82%E7%82%B9%22%5D%20--%3E%20B2%5B%22Ho%20%E4%B8%89%E8%A7%92%E5%BD%A2%E8%8A%82%E7%82%B9%20bump%22%5D%0A%20%20B1%20--%3E%20V%5B%22%E5%85%B3%E9%94%AE%E6%9C%9F%E9%99%90%20DV01%20%E5%90%91%E9%87%8F%22%5D%0A%20%20B2%20--%3E%20V%0A%20%20V%20--%3E%20J%5B%22%E5%AF%B9%E5%86%B2%E5%B7%A5%E5%85%B7%E9%9B%85%E5%8F%AF%E6%AF%94%22%5D%0A%20%20J%20--%3E%20X%5B%22%E8%A7%A3%E7%AF%AE%E5%AD%90%E5%90%8D%E4%B9%89%22%5D%0A%20%20V%20--%3E%20PCA%5B%22%E5%8A%A0%E6%80%BB%20%2F%20%E6%96%9C%E7%8E%87%20%2F%20%E6%9B%B2%E7%8E%87%E6%A0%B8%E5%AF%B9%22%5D%0A%20%20V%20--%3E%20PNL%5B%22PnL%20%E8%A7%A3%E9%87%8A%20%CE%A3%20DV01%20%CE%94y%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[s(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>关键期限 DV01 是关键点 1bp 冲击下的货币价值变化，等于把 Ho 的 KRD 货币化，供解对冲名义与 PnL 解释。</li><li>工具 bump 对齐可交易报价；节点 bump 对齐形状基；两者都要对账。</li><li>多曲线下是「曲线 × 期限」矩阵，互换价差与期限基差是独立列。</li><li>与 PCA 分层使用：三因子管大方差，关键桶管折缝；满桶对冲会放大噪声。</li><li>模型希腊字母必须映射到这些桶；含权产品用全价差分。</li><li>出处：Ho, <em>Journal of Fixed Income</em>, 1992；Golub &amp; Tilman, <em>Journal of Portfolio Management</em>, 1997；平行 01 见 Macaulay（1938）与 Hull 的 DV01 表述。</li></ul>',2))])}const B=n(h,[["render",D]]);export{f as __pageData,B as default};
